"""Actual provider helpers; no Game/process/profile operations."""
import unittest
import test_cas_grid_eof as eof

BOOT="""
function deltaActive(g,raw=220){g.ApexGridBegin(deltaRequest(g,raw,geometry));g.ApexGridStep(1,0);assert.ok(g.apexGridState.delta?.authority);return g.apexGridState;}
function keep(g){return {cells:g.mCells,ys:g.mCellsY,map:g.mCellIndexToDataIndexMap,positions:g.mCells.map(c=>c.y),visible:g.mCells.map(c=>c.visible)};}
function untouched(g,k){assert.equal(g.mCells,k.cells);assert.equal(g.mCellsY,k.ys);assert.equal(g.mCellIndexToDataIndexMap,k.map);assert.deepEqual(g.mCells.map(c=>c.y),k.positions);assert.deepEqual(g.mCells.map(c=>c.visible),k.visible);}
function loseReady(g){const s=deltaActive(g),foreign={nativeReplacement:true};s.ready=foreign;const k=keep(g);const receipt=g.ApexGridStep(64,0);assert.equal(receipt.phase,'authority-lost');assert.equal(s.ready,foreign);untouched(g,k);return {s,foreign,receipt};}
"""

class AuthorityTests(unittest.TestCase):
 def case(self,code):eof.EofTests.case(self,BOOT+"{"+code+"}")
 def test_same_state_ready_replacement_releases_only_our_unchanged_gate_and_lease(self):
  self.case("const g=eofGrid(),{s,foreign,receipt}=loseReady(g);assert.equal(receipt.lease_released,true);assert.equal(receipt.input_released,true);assert.equal(g.mbSuppressUpdates,false);assert.equal(s.lease,null);assert.equal(g.mGridView.mouseEnabled,true);assert.equal(g.mGridView.mouseChildren,true);assert.equal(receipt.scope.sim_id,'1');assert.equal(receipt.scope.native_kind,2);assert.equal(receipt.scope.shell_kind,4);assert.equal(s.ready,foreign);")
 def test_whole_state_replacement_and_malformed_vectors_are_not_traversed_or_restored(self):
  self.case("const g=eofGrid();deltaActive(g);const old=g.apexGridState,foreign={ready:{foreign:true},job:null,marker:'authoritative'},k=keep(g);g.apexGridState=foreign;g.mCellsY=null;g.mCellIndexToDataIndexMap=null;const bytes=JSON.stringify(foreign),receipt=g.ApexGridStep(64,0);assert.equal(receipt.phase,'authority-lost');assert.equal(g.apexGridState,foreign);assert.equal(JSON.stringify(foreign),bytes);assert.equal(g.mCells,k.cells);assert.equal(g.mCellsY,null);assert.equal(g.mCellIndexToDataIndexMap,null);assert.equal(g.ApexGridStatus().phase,'authority-lost');assert.equal(g.ApexGridPoolViews().length,0);assert.equal(g.ApexGridPoolDisplays().length,0);assert.equal(g.ApexGridCells.length,0);assert.equal(g.ApexGridMap.length,0);assert.equal(g.ApexGridGeometryFrame(),null);assert.equal(g.ApexGridPendingFrame(),true);")
 def test_stolen_or_external_lease_and_changed_input_flags_are_preserved(self):
  for change in ("s.lease={foreign:true};","s.externalSuppression=true;","g.mGridView.mouseChildren=true;"):
   self.case("const g=eofGrid(),s=deltaActive(g);"+change+"const lease=s.lease,external=s.externalSuppression,mouse=g.mGridView.mouseEnabled,children=g.mGridView.mouseChildren,k=keep(g);const receipt=g.ApexGridStep(64,0);assert.equal(receipt.phase,'authority-lost');assert.equal(receipt.lease_released,false);assert.equal(receipt.input_released,false);assert.equal(s.lease,lease);assert.equal(s.externalSuppression,external);assert.equal(g.mbSuppressUpdates,true);assert.equal(g.mGridView.mouseEnabled,mouse);assert.equal(g.mGridView.mouseChildren,children);untouched(g,k);")
 def test_ordinary_product_only_deltas_have_the_same_authority_fences(self):
  self.case("const g=new NativeGrid(1000,0);g.ApexGridBegin(deltaRequest(g,0,geometry));steps(g);const s=deltaActive(g,60),k=keep(g),foreign={pool:true};assert.equal(s.delta.eofWindow,false);s.poolFlags=foreign;const receipt=g.ApexGridStep(64,0);assert.equal(receipt.phase,'authority-lost');assert.equal(s.poolFlags,foreign);untouched(g,k);assert.equal(receipt.lease_released,true);")
 def test_terminal_frames_polling_begin_and_input_do_not_retry_or_touch_unknown_state(self):
  self.case("const g=eofGrid(),{s,foreign}=loseReady(g),k=keep(g),at=g.calls.length;for(let i=0;i<30;i++){assert.equal(g.ApexGridNeedsWork(),false);assert.equal(g.ApexGridStatus().phase,'authority-lost');assert.equal(g.ApexGridStep(64,0).phase,'authority-lost');assert.equal(g.ApexGridBegin(deltaRequest(g,220,geometry)).phase,'authority-lost');g.ApexGridBeginFrame(deltaRequest(g,220,geometry));assert.equal(g.ApexGridNativeGuard('input',{currentTarget:g.mCells[0]}),true);assert.equal(g.ApexGridPoolDataIndex(0),-1);}assert.equal(g.calls.length,at);assert.equal(s.ready,foreign);untouched(g,k);g.lease.generation++;assert.equal(g.ApexGridBegin(deltaRequest(g,220,geometry)).phase,'authority-lost');")
 def test_changed_scope_fresh_bound_measurement_rebind_clears_terminal_without_old_rollback(self):
  self.case("const g=eofGrid(),{s,foreign}=loseReady(g),k=keep(g);g.lease.state=8;const r=deltaRequest(g,0,Object.assign({},geometry,{bootstrap:true}));g.ApexGridBegin(r);assert.equal(g.ApexGridAuthorityStatus(),null);assert.notEqual(g.apexGridState,s);assert.equal(s.ready,foreign);untouched(g,k);assert.equal(g.apexGridState.bootstrap,true);")
 def test_recovery_cannot_discard_stolen_lease_before_or_during_validation(self):
  self.case("const g=eofGrid(),s=deltaActive(g);const stolen={foreign:true};s.lease=stolen;g.ApexGridStep(64,0);g.lease.state=8;let calls=0;const r=deltaRequest(g,0,Object.assign({},geometry,{bootstrap:true}));r.validate=()=>{calls++;return true;};assert.equal(g.ApexGridBegin(r).phase,'authority-lost');assert.equal(calls,0);assert.equal(s.lease,stolen);assert.equal(g.mbSuppressUpdates,true);s.lease=null;g.mbSuppressUpdates=false;r.validate=()=>{calls++;s.lease=stolen;g.mbSuppressUpdates=true;return true;};assert.equal(g.ApexGridBegin(r).phase,'authority-lost');assert.equal(g.apexGridState,s);assert.equal(s.lease,stolen);assert.equal(g.mbSuppressUpdates,true);")
 def test_real_disposal_drops_ui_handles_but_keeps_primitive_tombstone_until_bound_recovery(self):
  self.case("const g=eofGrid(),{s,foreign}=loseReady(g),held=g.apexGridAuthority;g.ApexGridCancel('dispose');assert.equal(g.apexGridAuthority,held);g.panel.stage=null;const receipt=g.ApexGridCancel('dispose');assert.equal(receipt.phase,'authority-lost');assert.equal(receipt.lifecycle_changed,true);assert.equal(g.apexGridAuthority.disposed,true);for(const key of['state','job','delta','owner','panel','view','feed','type','ready','pool','intrinsics','presentation'])assert.equal(key in g.apexGridAuthority,false);assert.equal(s.ready,foreign);g.panel.stage={fresh:true};g.ApexGridBegin(deltaRequest(g,0,Object.assign({},geometry,{bootstrap:true})));assert.equal(g.ApexGridAuthorityStatus(),null);")
 def test_exact_same_entry_ready_and_position_adoption_refuses_before_rollback(self):
  for change in ("s.ready[cell]=999;cell.y=777;","cell.y=777;","d.oldReady[cell]=999;cell.y=777;"):
   self.case("const g=eofGrid();g.ApexGridBegin(deltaRequest(g,220,geometry));for(let i=0;i<4000&&g.apexGridState.delta?.phase!=='textures';i++)g.ApexGridStep(1,0);const s=g.apexGridState,d=s.delta,cell=d.oldCells[0];assert.equal(d.phase,'textures');"+change+"const ready=s.ready,oldReady=d.oldReady,pool=s.poolFlags,cells=g.mCells,ys=g.mCellsY,map=g.mCellIndexToDataIndexMap,y=cell.y,visible=cell.visible;const receipt=g.ApexGridCancel('context');assert.equal(receipt.phase,'authority-lost');assert.equal(s.ready,ready);assert.equal(d.oldReady,oldReady);assert.equal(s.poolFlags,pool);assert.equal(g.mCells,cells);assert.equal(g.mCellsY,ys);assert.equal(g.mCellIndexToDataIndexMap,map);assert.equal(cell.y,y);assert.equal(cell.visible,visible);")

if __name__=='__main__':unittest.main()
